Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Fix icon drawing bug in 16-bit VDI

Icons were drawn incorrectly when they were partially covered by a
window.  This bug was introduced by commit 75f1af4.  Thanks to
David Henderson for reporting the problem.

Here is the root cause:
The bug was caused by an incorrect calculation of the source width (`src_width`) for drawing icons, which was based on `b_wd` instead of the correct value derived from `s_nxln`. This led to improper rendering of icons when they were partially covered by a window.

Here is the patch:
  */
 static void vrt_cpyfm16(struct blit_frame *info)
 {
     UWORD *src, *dst, *p, *q;
     WORD mode, src_width, src_off, dst_width, x, y;
     UWORD *palette, src_mask, bit_mask, fgcol, bgcol;

     mode = INTIN[0];

     palette = CUR_WORK->ext->palette;
     fgcol = palette[info->fg_col];
     bgcol = palette[info->bg_col];

     /*
      * init source area variables
      */
-    src_width = info->b_wd >> 4;            /* width in words */
+    src_width = info->s_nxln / sizeof(WORD);/* width in words */
     src_off = info->s_xmin >> 4;            /* starting x offset in words */
     bit_mask = src_mask = 0x8000U >> (info->s_xmin&0x000f); /* starting bit mask */
     p = src = info->s_form + ((LONG)info->s_ymin * src_width) + src_off;

     /*
      * init destination area variables
      */
     dst_width = v_lin_wr / sizeof(WORD);    /* in words */
     q = dst = info->d_form + ((LONG)info->d_ymin * dst_width) + info->d_xmin;

     switch(mode) {
     case MD_ERASE:
         for (y = info->s_ymin; y <= info->s_ymax; y++) {
             for (x = info->s_xmin; x <= info->s_xmax; x++, q++) {
                 if (!(*p & bit_mask))
                     *q = bgcol;
                 rorw1(bit_mask);
                 if (bit_mask & 0x8000)
                     p++;
             }
             src += src_width;
             p = src;
             bit_mask = src_mask;
             dst += dst_width;
             q = dst;
         }
         break;

     case MD_XOR:
         for (y = info->s_ymin; y <= info->s_ymax; y++) {
             for (x = info->s_xmin; x <= info->s_xmax; x++, q++) {
                 if (*p & bit_mask)
                     *q = ~*q;
                 rorw1(bit_mask);
                 if (bit_mask & 0x8000)
                     p++;
             }
             src += src_width;
             p = src;
             bit_mask = src_mask;
             dst += dst_width;
             q = dst;
         }
         break;

     case MD_TRANS:
         for (y = info->s_ymin; y <= info->s_ymax; y++) {
             for (x = info->s_xmin; x <= info->s_xmax; x++, q++) {
                 if (*p & bit_mask)
                     *q = fgcol;
                 rorw1(bit_mask);
                 if (bit_mask & 0x8000)
                     p++;
             }
             src += src_width;
             p = src;
             bit_mask = src_mask;
             dst += dst_width;
             q = dst;
         }
         break;

     case MD_REPLACE:
         for (y = info->s_ymin; y <= info->s_ymax; y++) {
             for (x = info->s_xmin; x <= info->s_xmax; x++, q++) {
                 if (*p & bit_mask)
                     *q = fgcol;
                 else
                     *q = bgcol;
                 rorw1(bit_mask);
                 if (bit_mask & 0x8000)
                     p++;
             }
             src += src_width;
             p = src;
             bit_mask = src_mask;
             dst += dst_width;
             q = dst;
         }
         break;

     default:
         return;                     /* unsupported mode */
     }
 }
 #endif


